import { delegate, type SafeHtml } from 'kerfjs';
import { PageHeader } from '@kerfjs/ui/page-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { StateBanner } from '@kerfjs/ui/state-banner';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import '@kerfjs/ui/layout.css';
import './tasks.css';

export interface Task { id: string; title: string; owner: string; status: string }
export function mountTasks(root: HTMLElement, app: {
  renderInto(root: HTMLElement, view: SafeHtml): void;
  fetchTasks(signal: AbortSignal): Promise<Task[]>;
  createTask(): void;
}) {
  // null means no successful response; [] means a successfully loaded empty list.
  let tasks: Task[] | null = null;
  let pending = false;
  let error: string | null = null;
  let controller: AbortController | undefined;
  let generation = 0;
  let disposed = false;
  const retry = () => <button class="task-button" type="button" data-action="tasks.refresh" disabled={pending}>Retry</button>;
  function render() {
    const state = error ? 'error' : pending ? tasks === null ? 'loading' : 'refreshing' : tasks?.length ? 'populated' : 'empty';
    app.renderInto(root, <section class="tasks kui-layout" data-state={state} aria-label="Release tasks">
      <PageHeader title="Release tasks" action={<button class="task-button" type="button" data-action="tasks.refresh" disabled={pending}>Refresh</button>} />
      <div class="kui-scroll-owner kui-pane-body kui-section-stack">
        {error && <StateBanner title={tasks === null ? 'Tasks could not be loaded' : 'Tasks could not be refreshed'}
          detail={tasks === null ? error : error + ' Your last successful results remain below.'}
          tone="danger" urgency="alert" action={retry()} />}
        {pending && tasks !== null && <StateBanner title="Showing saved results" detail="Refreshing tasks in the background."
          tone="info" action={<LoadingSpinner label="Refreshing tasks" />} />}
        <div aria-busy={String(pending)} class="kui-section-stack">
          {tasks === null ? (pending ? <EmptyState title="Loading tasks" detail="Getting the current workspace." busy />
            : <EmptyState title="Tasks are unavailable" detail="Use Retry above to try again." />)
            : tasks.length === 0 ? <EmptyState title="No release tasks yet" detail="Create a task to start planning this release."
                action={<button class="task-button" type="button" data-action="tasks.create">Create task</button>} />
              : <ul class="task-list" aria-label="Release tasks">{tasks.map(task => <li data-key={task.id}>
                  <strong>{task.title}</strong><span class="kui-inline-metadata">{task.status} · {task.owner}</span>
                </li>)}</ul>}
        </div>
        <p role="status" aria-live="polite" aria-atomic="true" class="task-count">
          {!pending && !error && tasks !== null ? tasks.length + (tasks.length === 1 ? ' task loaded' : ' tasks loaded') : ''}
        </p>
      </div>
    </section>);
  }
  async function load() {
    controller?.abort();
    controller = new AbortController();
    const request = ++generation;
    pending = true;
    // Leave an existing failure visible during retry; clear only after success.
    render();
    try {
      const next = await app.fetchTasks(controller.signal);
      if (disposed || request !== generation) return;
      tasks = next; error = null;
    } catch (cause) {
      if (disposed || request !== generation || controller.signal.aborted) return;
      error = 'Check your connection and try again.';
    } finally {
      if (!disposed && request === generation) { pending = false; render(); }
    }
  }
  const disposeActions = delegate(root, 'click', '[data-action]', (_event, element) => {
    const action = (element as HTMLElement).dataset.action;
    if (action === 'tasks.refresh' && !pending) void load();
    if (action === 'tasks.create') app.createTask();
  });
  void load();
  return () => { disposed = true; generation++; controller?.abort(); disposeActions(); };
}

