.tasks { display: grid; grid-template-rows: auto minmax(0, 1fr); height: 100%; min-height: 0; min-width: 0; color: var(--kui-color-text); background: var(--kui-color-surface); }
.tasks .kui-scroll-owner { min-height: 0; overflow-wrap: anywhere; }
.task-list { list-style: none; margin: 0; padding: 0; }
.task-list li { display: grid; gap: var(--kui-layout-metadata-gap); padding-block: var(--kui-space-s); border-block-end: 1px solid var(--kui-color-border); }
.task-count { margin: 0; color: var(--kui-color-text-quiet); }
.task-button { font: inherit; min-height: 2.25rem; padding: var(--kui-space-xs) var(--kui-space-s); color: var(--kui-color-text); background: var(--kui-color-surface); border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); }
.task-button:focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
